/*
 * A040490  Continued fraction for sqrt(513).
 * https://oeis.org/A040490
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   a(n) = continued fraction coefficient of sqrt(513) The continued
 *            fraction of √513 is periodic. The first term a(0) = ⌊√513⌋ = 22.
 *            Subsequent terms are generated by the standard recurrence for
 *            quadratic irrationals:
 * Range:     u8 none, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Static storage for the period of the continued fraction.  The
   period of √N never exceeds 2*⌊√N⌋, so an array of 128 elements
   is more than enough for N = 513.  The array is filled once on the
   first call to a(). */
static seq_t  period[128];
static size_t period_len = 0;
static bool   ready      = false;

/* Initialise the period.  Only called once. */
static void init(void)
{
    if (ready)
        return;

    const seq_t a0 = (seq_t)22;          /* ⌊√513⌋ */
    const seq_t S  = (seq_t)513;         /* the radicand */

    seq_t m = 0;
    seq_t d = 1;
    seq_t a = a0;

    while (1) {
        seq_t m_next = d * a - m;
        seq_t d_next = (S - m_next * m_next) / d;
        seq_t a_next = (a0 + m_next) / d_next;

        period[period_len++] = a_next;

        /* The period ends when the next term equals 2*a0. */
        if (a_next == a0 * (seq_t)2)
            break;

        m = m_next;
        d = d_next;
        a = a_next;
    }

    ready = true;
}

seq_t a(idx_t n)
{
    if (!ready)
        init();

    if (n == 0)
        return (seq_t)22;   /* a(0) = ⌊√513⌋ */

    /* Index into the period.  (n-1) is safe for n ≥ 1.  */
    size_t idx = (size_t)((n - 1) % period_len);
    return period[idx];
}
